import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.F7eQ-ohH.js";const l="/bzygq/assets/00f792a12f444518ac0270ad5a28d12b.C5gf27jl.png",s="/bzygq/assets/bc88af334fbd4e66a97e1d742057ad70.YU9arm5d.png",c=JSON.parse('{"title":"02 连接建立、会话状态与保活机制","description":"","frontmatter":{},"headers":[],"relativePath":"Java面试问题汇总/MQTT/02 连接建立、会话状态与保活机制.md","filePath":"Java面试问题汇总/MQTT/02 连接建立、会话状态与保活机制.md","lastUpdated":1788929995000}'),o={name:"Java面试问题汇总/MQTT/02 连接建立、会话状态与保活机制.md"};function r(d,e,p,T,C,S){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="_02-连接建立、会话状态与保活机制" tabindex="-1">02 连接建立、会话状态与保活机制 <a class="header-anchor" href="#_02-连接建立、会话状态与保活机制" aria-label="Permalink to &quot;02 连接建立、会话状态与保活机制&quot;">​</a></h1><p>MQTT 的连接建立不是简单的 TCP 三次握手之后就开始收发消息，而是在一条已经建立的网络连接上，用 CONNECT 和 CONNACK 完成协议层建链。这个过程会同时确定协议版本、认证信息、客户端身份、会话是否复用、会话过期策略、保活周期和遗嘱消息。换句话说，MQTT 的“连接”实际上由两层组成：底层 TCP/TLS 连接负责字节传输，MQTT 网络连接负责协议状态，Session 负责订阅、离线消息和未完成 QoS 流程。</p><p>理解这一章时，要把 Client Identifier、Clean Start/Clean Session、Session Expiry Interval、Keep Alive、Will Message 放在同一条链路里看。很多 Java 项目里的 MQTT 问题，例如服务重启后订阅丢失、同一设备反复被踢下线、离线消息没有收到、连接看起来还在但业务已经失联，本质上都不是“消息中间件偶发不稳定”，而是连接身份、会话生命周期和保活参数没有设计清楚。</p><h2 id="connect-和-connack-决定协议层连接是否成立" tabindex="-1">CONNECT 和 CONNACK 决定协议层连接是否成立 <a class="header-anchor" href="#connect-和-connack-决定协议层连接是否成立" aria-label="Permalink to &quot;CONNECT 和 CONNACK 决定协议层连接是否成立&quot;">​</a></h2><p>MQTT 客户端必须先向服务端发送 CONNECT 报文，服务端只能返回一个 CONNACK 作为建链结果。客户端在发送 CONNECT 之前可以已经完成 TCP 或 TLS 握手，但在收到成功的 CONNACK 之前，不能把这条网络连接当作可用的 MQTT 会话。服务端如果不接受连接，会在 CONNACK 中返回失败原因，或者直接关闭网络连接。</p><h3 id="connect-承载的是连接契约" tabindex="-1">CONNECT 承载的是连接契约 <a class="header-anchor" href="#connect-承载的是连接契约" aria-label="Permalink to &quot;CONNECT 承载的是连接契约&quot;">​</a></h3><p>CONNECT 报文里最关键的字段不是用户名密码，而是连接契约本身。它至少包括协议名和协议级别、连接标志、Keep Alive、Client Identifier，以及可选的 Will、用户名、密码。MQTT 5.0 还通过属性扩展出 Session Expiry Interval、Receive Maximum、Maximum Packet Size、Topic Alias Maximum、认证方法和用户属性等能力。服务端会根据这些字段判断客户端是否符合协议、是否通过认证、是否允许建立或恢复会话。</p><p>从工程角度看，CONNECT 是客户端对服务端提出的一组约束：我是谁，我要不要清理旧会话，我希望会话断开后保存多久，我多久至少发一个控制报文，我异常掉线时是否发布遗嘱消息。服务端返回 CONNACK，表示这些约束被接受、被调整或被拒绝。因此连接失败排查不能只看网络端口通不通，还要看协议版本、ClientId、认证、ACL、最大报文、服务端连接数、服务端对空 ClientId 或持久会话的限制。</p><h3 id="connack-不只是成功或失败" tabindex="-1">CONNACK 不只是成功或失败 <a class="header-anchor" href="#connack-不只是成功或失败" aria-label="Permalink to &quot;CONNACK 不只是成功或失败&quot;">​</a></h3><p>CONNACK 至少包含连接确认标志和原因码。MQTT 3.1.1 中常见的是连接返回码，MQTT 5.0 中则使用 Reason Code 和属性表达更细的拒绝原因或服务端能力。对于会话机制而言，Session Present 是最容易被忽略的字段：它告诉客户端服务端是否找到了与当前 Client Identifier 关联的既有会话。Clean Start 为 1 时，MQTT 5.0 规定 Session Present 必须为 0，因为客户端和服务端都已经丢弃旧会话并开启新会话。</p><p>Java 客户端集成时，不建议只在日志里打印“connected”。更有价值的是把 CONNACK 的原因码、Session Present、服务端分配的 Client Identifier、最大报文限制、接收窗口等信息记录下来。它们能直接解释后续行为：为什么重连后没有离线消息，为什么订阅需要重新发，为什么 QoS 1 消息吞吐上不去，为什么某些大 payload 被服务端拒绝。</p><p><img src="'+l+'" alt="images/mqtt-02-connect-handshake-timeline.png"></p><p>images/mqtt-02-connect-handshake-timeline.png</p><h2 id="client-identifier-是会话身份-不是随手起的连接名" tabindex="-1">Client Identifier 是会话身份，不是随手起的连接名 <a class="header-anchor" href="#client-identifier-是会话身份-不是随手起的连接名" aria-label="Permalink to &quot;Client Identifier 是会话身份，不是随手起的连接名&quot;">​</a></h2><p>Client Identifier 是 MQTT 用来识别客户端会话的主键。服务端根据它决定当前连接是否与已有会话关联，也根据它处理同一 ClientId 的重复连接。对于设备接入、车联网、物联网网关、业务服务消费 MQTT Topic 这类场景，ClientId 的设计等价于会话身份设计，不能当作日志里的实例名随手生成。</p><p>如果两个活跃连接使用同一个 ClientId，服务端通常会关闭旧连接，让新连接接管该身份。这不是负载均衡，而是协议身份冲突。很多 Java 服务在 Kubernetes 中水平扩容后，如果所有 Pod 使用同一个配置文件里的固定 ClientId，就会出现多个实例轮流把彼此踢下线的现象；如果每次启动都用 UUID 生成 ClientId，又会导致服务端无法复用旧会话，离线消息和未完成 QoS 状态也无法按预期恢复。</p><h3 id="稳定-clientid-和动态-clientid-的取舍" tabindex="-1">稳定 ClientId 和动态 ClientId 的取舍 <a class="header-anchor" href="#稳定-clientid-和动态-clientid-的取舍" aria-label="Permalink to &quot;稳定 ClientId 和动态 ClientId 的取舍&quot;">​</a></h3><p>稳定 ClientId 适合需要会话恢复的客户端，例如设备端、边缘网关、固定业务消费者。它的优势是重连后可以继续使用服务端保存的订阅和未完成消息状态，但要求同一时刻只有一个实例持有该身份，并且要有明确的主备或分片策略。动态 ClientId 适合短连接、无状态采集、只发布不上线恢复的客户端，它避免身份冲突，但意味着每次连接都是新身份，不能依赖旧会话。</p><p>MQTT 5.0 支持服务端分配 Client Identifier，适合客户端确实不关心持久身份的场景。项目里要注意，一旦客户端需要持久订阅、离线消息或故障恢复，就不能把“空 ClientId 让服务端分配”当成默认方案，因为下次连接拿到的身份可能不同。更稳的做法是把设备编号、租户编号、业务消费者分片号纳入 ClientId 规划，并在服务端侧配合 ACL 和连接数限制。</p><h2 id="clean-start、clean-session-和-session-expiry-控制会话生命周期" tabindex="-1">Clean Start、Clean Session 和 Session Expiry 控制会话生命周期 <a class="header-anchor" href="#clean-start、clean-session-和-session-expiry-控制会话生命周期" aria-label="Permalink to &quot;Clean Start、Clean Session 和 Session Expiry 控制会话生命周期&quot;">​</a></h2><p>MQTT 3.1.1 使用 Clean Session 一个标志同时表达“是否丢弃旧会话”和“断开后是否保存当前会话”。MQTT 5.0 把它拆成两个维度：Clean Start 决定本次连接开始时是否清理旧会话，Session Expiry Interval 决定网络连接关闭后会话状态保存多久。这个拆分使语义更精确，也让 Java 客户端迁移版本时更容易踩坑。</p><table tabindex="0"><thead><tr><th>版本</th><th>建链时的控制项</th><th>断开后的会话保存</th><th>常见理解</th></tr></thead><tbody><tr><td>MQTT 3.1.1</td><td>Clean Session=1</td><td>当前网络连接结束后不复用会话状态</td><td>每次都是临时会话</td></tr><tr><td>MQTT 3.1.1</td><td>Clean Session=0</td><td>客户端和服务端断开后仍保存会话</td><td>可恢复订阅和未完成消息</td></tr><tr><td>MQTT 5.0</td><td>Clean Start=1</td><td>先丢弃已有会话，再创建新会话；之后保存多久由 Session Expiry 决定</td><td>“从干净状态启动”</td></tr><tr><td>MQTT 5.0</td><td>Clean Start=0</td><td>有旧会话则恢复，没有旧会话则创建新会话；之后保存多久由 Session Expiry 决定</td><td>“尽量延续旧会话”</td></tr></tbody></table><h3 id="mqtt-5-0-的过期时间是独立轴" tabindex="-1">MQTT 5.0 的过期时间是独立轴 <a class="header-anchor" href="#mqtt-5-0-的过期时间是独立轴" aria-label="Permalink to &quot;MQTT 5.0 的过期时间是独立轴&quot;">​</a></h3><p>OASIS MQTT 5.0 规定，Clean Start=1 时，客户端和服务端必须丢弃当前 Client Identifier 对应的已有会话并开启新会话。如果 Session Expiry Interval 缺省，值按 0 处理；为 0 时，网络连接关闭后会话结束；为 0xFFFFFFFF 时，会话不过期。只要过期时间大于 0，网络连接关闭后客户端和服务端就需要保存 Session State，直到过期时间到达或被管理策略清理。</p><p>这意味着 Clean Start=1 不等于“永远不保存会话”。例如客户端可以用 Clean Start=1 清掉历史脏状态，同时把 Session Expiry Interval 设置成 1 小时，让新会话在之后的异常断开中仍可恢复。反过来，Clean Start=0 也不等于“永久会话”，如果过期时间是 0，断开后仍然不会保存。很多迁移问题正是把 MQTT 3.1.1 的 Clean Session 直觉直接套到 MQTT 5.0 上，导致会话保留行为和预期相反。</p><h3 id="订阅恢复不等于业务状态恢复" tabindex="-1">订阅恢复不等于业务状态恢复 <a class="header-anchor" href="#订阅恢复不等于业务状态恢复" aria-label="Permalink to &quot;订阅恢复不等于业务状态恢复&quot;">​</a></h3><p>会话保存的是 MQTT 协议状态，不是业务应用的全部状态。服务端可以保存订阅、未确认的 QoS 1/QoS 2 消息、等待发送给客户端的 QoS 1/QoS 2 消息，以及可选的 QoS 0 待发送消息。客户端侧也要保存自己已经发送但未完成确认的 QoS 1/QoS 2 流程，以及收到但未完成确认的 QoS 2 流程。若 Java 客户端库没有启用持久化存储，或者进程重启后本地 inflight 状态丢失，就算服务端保存了会话，端到端语义也可能退化。</p><p>因此项目里要把 MQTT 会话恢复和业务幂等分开设计。会话恢复负责尽量不丢协议层消息，业务幂等负责处理重复投递、重连重放和处理到一半失败。对订单状态、设备指令、告警事件这类数据，不能把“使用 QoS 1 并开启持久会话”等同于“业务绝对不重复且不丢”。更稳的做法是在消息体中带业务唯一 ID、版本号或幂等键，消费端落库时做去重和状态校验。</p><h2 id="session-state-由订阅和未完成消息共同构成" tabindex="-1">Session State 由订阅和未完成消息共同构成 <a class="header-anchor" href="#session-state-由订阅和未完成消息共同构成" aria-label="Permalink to &quot;Session State 由订阅和未完成消息共同构成&quot;">​</a></h2><p>MQTT 的 Session State 可以理解为服务端和客户端围绕同一 ClientId 保存的一组协议进度。服务端侧包括会话存在本身、客户端订阅关系、已经发给客户端但还没有完成确认的 QoS 1/QoS 2 消息、等待传输给客户端的 QoS 1/QoS 2 消息、可选的 QoS 0 待传输消息、已经从客户端收到但 QoS 2 流程未完成的消息，以及会话将在何时结束。客户端侧主要保存已发送未完成确认的 QoS 1/QoS 2 消息，以及已收到但未完成确认的 QoS 2 消息。</p><p><img src="'+s+'" alt="images/mqtt-02-session-keepalive-state.png"></p><p>images/mqtt-02-session-keepalive-state.png</p><p>这张图可以按三层理解：最上层是 CONNECT/CONNACK 建链时确定身份和会话策略，中间层是 Session State 保存订阅与 QoS 确认进度，底层是 Keep Alive 用控制报文检测网络连接是否仍然可用。网络连接断开不一定意味着会话立即消失，会话存在也不意味着底层连接仍然活着。MQTT 的可靠性设计正是把“连接是否在线”和“会话是否可恢复”拆开处理。</p><h3 id="retained-message-不属于-session-state" tabindex="-1">Retained Message 不属于 Session State <a class="header-anchor" href="#retained-message-不属于-session-state" aria-label="Permalink to &quot;Retained Message 不属于 Session State&quot;">​</a></h3><p>保留消息容易和会话离线消息混在一起。Retained Message 是服务端在某个 Topic 上保存的最后一条保留发布，用于让新订阅者立即拿到该 Topic 的当前值；Session State 则是围绕某个 ClientId 保存的订阅与消息确认进度。MQTT 5.0 规范明确，服务端的 Retained Message 不属于 Session State，不会因为某个会话结束而被删除。</p><p>项目里可以这样区分：设备最新状态、配置快照、开关当前值适合用 retained；某个客户端断线期间需要补发的事件流，依赖持久会话和 QoS。不要用 retained 模拟消息队列，因为它只保留一个 Topic 的最后值；也不要以为删除会话会清掉 Topic 上的 retained 状态，它们的生命周期完全不同。</p><h2 id="keep-alive-用-pingreq-pingresp-约束沉默连接" tabindex="-1">Keep Alive 用 PINGREQ/PINGRESP 约束沉默连接 <a class="header-anchor" href="#keep-alive-用-pingreq-pingresp-约束沉默连接" aria-label="Permalink to &quot;Keep Alive 用 PINGREQ/PINGRESP 约束沉默连接&quot;">​</a></h2><p>MQTT 3.1.1 规定 Keep Alive 是秒级时间间隔，表示客户端发送完一个控制报文到开始发送下一个控制报文之间允许经过的最大时间。只要客户端在这个周期内发送了任何 MQTT 控制报文，就不需要额外发送心跳；如果没有其他控制报文，客户端必须发送 PINGREQ。服务端收到 PINGREQ 后返回 PINGRESP，客户端可以据此判断网络和服务端仍然可用。</p><h3 id="_1-5-倍规则决定服务端断线判断" tabindex="-1">1.5 倍规则决定服务端断线判断 <a class="header-anchor" href="#_1-5-倍规则决定服务端断线判断" aria-label="Permalink to &quot;1.5 倍规则决定服务端断线判断&quot;">​</a></h3><p>当 Keep Alive 非 0 时，如果服务端在 1.5 倍 Keep Alive 时间内没有收到客户端任何控制报文，服务端必须把这条网络连接当作失败连接并断开。客户端发出 PINGREQ 后，如果在合理时间内没有收到 PINGRESP，也应该关闭网络连接并重新建立连接。Keep Alive 为 0 表示关闭 MQTT 层保活机制，服务端不需要因为空闲而按 Keep Alive 规则断开，但服务端仍然可以基于自己的策略关闭不活跃或无响应连接。</p><p>这个规则解释了一个常见现象：业务消息频繁时没有 PINGREQ，并不代表心跳失效，因为业务控制报文本身已经刷新了 Keep Alive 计时；业务安静时才会看到 PINGREQ/PINGRESP。抓包排查时要看的是“是否超过 Keep Alive 没有任何 MQTT 控制报文”，而不是机械地要求每隔固定秒数一定出现一次 PINGREQ。</p><h3 id="java-项目里的保活参数不要孤立配置" tabindex="-1">Java 项目里的保活参数不要孤立配置 <a class="header-anchor" href="#java-项目里的保活参数不要孤立配置" aria-label="Permalink to &quot;Java 项目里的保活参数不要孤立配置&quot;">​</a></h3><p>Keep Alive 要和网络环境、代理层、服务端空闲超时、客户端重连策略一起设计。值太小会带来大量心跳报文和误判，尤其是移动网络、弱网、TLS 握手成本高的场景；值太大又会让半开连接暴露得很慢，设备已经离线但服务端长时间不知道。生产里通常会让 MQTT Keep Alive 小于四层负载均衡、NAT、防火墙的空闲回收时间，并配合客户端自动重连和指数退避。</p><p>Java 客户端还要注意线程模型。部分库把网络读写、回调和重连调度放在有限线程里，如果业务回调里执行耗时数据库操作、HTTP 调用或阻塞锁等待，就可能拖慢协议处理，导致 PINGRESP 处理不及时或确认报文发送延迟。正确做法是让 MQTT 回调尽快投递到业务线程池或队列，协议线程只做轻量解析、确认和转发，避免把业务耗时压到连接保活链路上。</p><h2 id="will-message-和-disconnect-定义异常离线语义" tabindex="-1">Will Message 和 DISCONNECT 定义异常离线语义 <a class="header-anchor" href="#will-message-和-disconnect-定义异常离线语义" aria-label="Permalink to &quot;Will Message 和 DISCONNECT 定义异常离线语义&quot;">​</a></h2><p>Will Message 是客户端在 CONNECT 时预先交给服务端的一条遗嘱消息，用来通知其他订阅者“这个客户端异常离线”。当连接请求被接受且 Will Flag 设置为 1 时，服务端必须把 Will 与当前网络连接关联。网络连接异常关闭时，服务端会发布 Will；正常收到客户端的 DISCONNECT 后，服务端通常会删除 Will 而不发布。</p><h3 id="哪些断开会触发-will" tabindex="-1">哪些断开会触发 Will <a class="header-anchor" href="#哪些断开会触发-will" aria-label="Permalink to &quot;哪些断开会触发 Will&quot;">​</a></h3><p>在 MQTT 3.1.1 中，触发 Will 的典型场景包括服务端检测到 I/O 错误或网络失败、客户端在 Keep Alive 时间内没有通信、客户端没有先发送 DISCONNECT 就关闭网络连接、服务端因协议错误关闭连接。MQTT 5.0 也保留这个核心语义，并通过 Will Delay Interval 等属性让服务端可以延迟发布遗嘱，从而给短暂重连留出缓冲空间。</p><p>Will 的价值在于表达“异常离线”，不适合表达“正常下线”。例如设备网关可以在连接时设置 Will Topic 为 device/{id}/status，payload 为 offline，并在正常上线后发布 retained 的 online 状态。只要网关异常断电或网络中断，服务端发布 Will，订阅方就能感知离线；如果网关按流程发送正常 DISCONNECT，Will 会被移除，不会误报异常。</p><h3 id="正常断开要先处理会话和业务状态" tabindex="-1">正常断开要先处理会话和业务状态 <a class="header-anchor" href="#正常断开要先处理会话和业务状态" aria-label="Permalink to &quot;正常断开要先处理会话和业务状态&quot;">​</a></h3><p>客户端主动下线时应发送 DISCONNECT，再关闭底层连接。MQTT 5.0 的 DISCONNECT 还可以携带原因码和新的 Session Expiry Interval，用来调整会话结束策略。比如某些客户端平时使用较长会话过期时间，但在用户退出登录或设备解绑时，可以通过正常断开把会话过期时间改为 0，使服务端尽快清理订阅和待发送状态。</p><p>Java 项目里常见的坑是直接 close() Socket、杀进程或让容器 SIGTERM 超时退出，没有给 MQTT 客户端机会发送 DISCONNECT 和完成 inflight 消息处理。这样服务端会把它当作异常断开，可能触发 Will，也可能保留会话等待过期。服务停机脚本和 Spring Bean 生命周期里应显式调用客户端断开方法，设置合理等待时间，并确保业务线程池先停止接收新任务、再排空待确认消息、最后关闭 MQTT 连接。对于必须快速下线的场景，也要清楚这是在用异常断开的语义换取退出速度。</p><h3 id="本章需要掌握的判断线" tabindex="-1">本章需要掌握的判断线 <a class="header-anchor" href="#本章需要掌握的判断线" aria-label="Permalink to &quot;本章需要掌握的判断线&quot;">​</a></h3><p>MQTT 建链要先看 CONNECT/CONNACK，因为它决定协议连接是否成立；会话恢复要看 ClientId、Clean Start 或 Clean Session、Session Expiry Interval，因为它们共同决定旧状态是否可复用、断开后是否保存；离线消息和订阅恢复要看 Session State，因为订阅、QoS 1/QoS 2 未完成确认和待发送消息才是会话的主体；连接探活要看 Keep Alive 和 PINGREQ/PINGRESP，因为没有业务报文时客户端必须主动维持控制报文节奏；异常离线通知要看 Will Message 和正常 DISCONNECT，因为 Will 只应该表达异常断开。</p><p>面试或项目复盘时，可以按一条完整链路表达：客户端用稳定 ClientId 发起 CONNECT，通过 Clean Start 或 Clean Session 决定是否清理旧会话，通过 Session Expiry 决定断开后保存多久；服务端用 CONNACK 返回是否接受连接以及是否存在旧会话；连接期间订阅和未完成 QoS 状态构成 Session State；空闲时客户端按 Keep Alive 发送 PINGREQ，服务端用 1.5 倍规则识别失联；客户端正常退出发送 DISCONNECT 并移除 Will，异常断开则由服务端发布 Will。能把这条链路讲清楚，MQTT 的连接稳定性、离线消息、重复投递和设备上下线问题就有了统一分析框架。</p>',55)])])}const N=a(o,[["render",r]]);export{c as __pageData,N as default};
